                    "sql": "create or replace table sleepycat_db.maplemonk.po_grn_analysis as with base as ( select po_id, grn_Id, grn_status, po_created_date::Date po_Date, inwarded_WArehouse, grn.value:model_no::string sku, sum(grn.value:available::float) grn_quantity, sum(grn.value:original_quantity::float) po_quantity, from sleepycat_db.maplemonk.easyecom_sleepycat_grn_details, LATERAL FLATTEN(input => grn_items) AS grn, group by 1,2,3,4,5,6 ) select b.*,sm_category as Category,sub_category from base b left join ( select upper(trim(marketplace_sku)) as sm_sku, category as sm_category, sub_category from sleepycat_db.maplemonk.final_sku_master qualify row_number() over(partition by upper(trim(marketplace_sku)) order by 1) = 1 )sm on lower(trim(b.sku)) = lower(trim(sm.sm_sku)) ; create or replace table sleepycat_db.maplemonk.sleepycat_fifo_report as select CONVERT_TIMEZONE(\'Asia/Kolkata\',TO_TIMESTAMP_TZ(_AIRBYTE_NORMALIZED_AT))::DATE AS Data_Fetch_Date, upper(sku) as sku, \"Company Name\" as Compnay_Name, upper(coalesce(sm_category,category)) as Category, sub_category, \"Days In Warehouse\" days_in_warehouse, sum(quantity) quantity from ( select * from sleepycat_db.maplemonk.easyecom_sleepycat_full_inventory_report qualify DENSE_RANK() over(partition by _airbyte_normalized_at::timestamp::date order by 1 desc) = 1 ) fi left join ( select upper(trim(marketplace_sku)) as sm_sku, category as sm_category, sub_category from sleepycat_db.maplemonk.final_sku_master qualify row_number() over(partition by upper(trim(marketplace_sku)) order by 1) = 1 )sm on lower(trim(fi.sku)) = lower(trim(sm.sm_sku)) where lower(status) in (\'available\',\'reserved\') and lower(\"Company Name\") in (\'vsl-cdp\', \'central distribution point\', \'sleep management pvt tdl mumbai warehouse\',\'sleep management pvt ltd chennai warehouse\',\'sleep management farukhnagar\',\'sleep management pvt ltd bangalore new warehouse\',\'hyderabad warehouse\', \'sleep management kolkata\') group by 1,2,3,4,5,6 ; Create Or Replace table sleepycat_db.maplemonk.sleepycat_db_warehouse_capacity_tracker as With Base as ( select DATEADD(day, 1, TO_TIMESTAMP(\"Report Generated Date\", \'YYYY-MM-DD HH24:MI:SS\'))::date DATA_FETCH_DATE, replace(replace(SKU,\'\\'\',\'\'),\'`\',\'\') SKU, Location as Warehouse, coalesce(a1.name,a2.name) Name, coalesce(a1.CATEGORY,a2.CATEGORY) CATEGORY, coalesce(a1.SUB_CATEGORY,a2.SUB_CATEGORY) SUB_CATEGORY, upper(trim(coalesce(a1.CAPACITY_CATEGORY,a2.CAPACITY_CATEGORY))) as CAPACITY_CATEGORY, sum(\"Available Quantity\"::int) AVAILABLEINVENTORY, from ( select * from sleepycat_db.maplemonk.sleepycat_db_inventory_snapshot qualify row_number() over (partition by location, \"Company Token\", SKU, DATEADD(day, 1, TO_TIMESTAMP(\"Report Generated Date\", \'YYYY-MM-DD HH24:MI:SS\'))::date order by \"Report Generated Date\") = 1 )s left join ( select * from sleepycat_db.maplemonk.final_sku_master qualify ROW_NUMBER() OVER(partition by MARKETPLACE_SKU order by 1) = 1 )a1 on lower(replace(replace(s.SKU,\'\\'\',\'\'),\'`\',\'\')) = lower(a1.MARKETPLACE_SKU) left join ( select * from sleepycat_db.maplemonk.final_sku_master qualify ROW_NUMBER() OVER(partition by skucode order by 1) = 1 )a2 on lower(replace(replace(s.SKU,\'\\'\',\'\'),\'`\',\'\')) = lower(a2.skucode) where DATA_FETCH_DATE is not null group by 1,2,3,4,5,6,7 ) Select b.*,div0(cm.Capacity,count(*) over(partition by lower(trim(b.Capacity_Category)),lower(trim(b.Warehouse)),b.DATA_FETCH_DATE)) as Capacity from Base b left join ( select * from (select upper(trim(warehouse)) as Warehouse ,\'ACC\' as Capacity_Category ,try_cast(ACC as int) as Capacity from sleepycat_db.maplemonk.sleepycat_db_capacity_mapping UNION ALL select upper(trim(warehouse)) as Warehouse ,\'MATTRESS\' as Capacity_Category ,try_cast(MATTRESS as int) as Capacity from sleepycat_db.maplemonk.sleepycat_db_capacity_mapping UNION ALL select upper(trim(warehouse)) as Warehouse ,\'FURNITURE\' as Capacity_Category ,try_cast(FURNITURE as int) as Capacity from sleepycat_db.maplemonk.sleepycat_db_capacity_mapping ) QUALIFY row_number() over(partition by Warehouse,Capacity_Category order by 1) = 1 )cm on lower(trim(b.Capacity_Category)) = lower(trim(cm.Capacity_Category)) and lower(trim(cm.Warehouse)) = lower(trim(b.Warehouse)) ; Create or Replace table SLEEPYCAT_DB.MAPLEMONK.Sleepycat_DB_Returns_performance_GoogleSheet as select SKU, WEEK, Status, Category, Pincode, COURIER, TAT, \"Cover Awb\" as Cover_AWB, \"Order id\" as order_id, \"Reverse Awb\" Reverse_AWB, \"Cover Zone\" Cover_Zone, \"Reverse Zone\" as Reverse_Zone, \"New Status\" as Status2, \"Final Status\", \"Reverse Awb\", TO_DATE(\"Return Raise date\", \'DD-MM-YYYY\') as Return_Raise_Date, TO_DATE(\"ReversePickup Date\", \'DD-MM-YYYY\') as ReturnPickup_Date, DATEDIFF(\'day\', TO_DATE(\"Return Raise date\", \'DD-MM-YYYY\'), TO_DATE(\"ReversePickup Date\", \'DD-MM-YYYY\') ) AS Return_Pickup_TAT from sleepycat_db.maplemonk.sleepycat_db_google_sheet_returns_sheet1;",
